CREATE TABLE "cities" (
	"id" text PRIMARY KEY NOT NULL,
	"country_id" text NOT NULL,
	"slug" text NOT NULL,
	"name" jsonb NOT NULL,
	"lat" double precision NOT NULL,
	"lng" double precision NOT NULL,
	"position" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "cities_position_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	CONSTRAINT "cities_slug_unique" UNIQUE("slug"),
	CONSTRAINT "cities_lat" CHECK ("cities"."lat" between -90 and 90),
	CONSTRAINT "cities_lng" CHECK ("cities"."lng" between -180 and 180),
	CONSTRAINT "cities_name" CHECK ((jsonb_typeof("cities"."name" -> 'ar') = 'string' and jsonb_typeof("cities"."name" -> 'en') = 'string') is true)
);
